<template>
	<!-- Bottom-sheet "Kembalikan ke Stok" untuk TTS/BSTK. Aturannya (status,
	     role, alasan wajib, blokir Oper PIC/Regis menggantung) ada di server:
	     juragan.collection.kembalikan_stok. -->
	<Teleport to="body">
		<Transition
			enter-active-class="transition-opacity duration-200"
			enter-from-class="opacity-0"
			leave-active-class="transition-opacity duration-150"
			leave-to-class="opacity-0"
		>
			<div
				v-if="open"
				class="fixed inset-0 z-[70] flex items-end justify-center bg-black/40"
				@click.self="tutup"
			>
				<Transition
					appear
					enter-active-class="transition-transform duration-200 ease-out"
					enter-from-class="translate-y-full"
					leave-active-class="transition-transform duration-150 ease-in"
					leave-to-class="translate-y-full"
				>
					<div
						v-if="open"
						class="max-h-[88dvh] w-full max-w-screen-sm overflow-y-auto overscroll-contain rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 text-xs shadow-2xl"
					>
						<div class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300" />
						<h2 class="text-center text-base font-semibold text-ui-ink-gray-900">
							Kembalikan ke Stok
						</h2>
						<p class="mb-4 mt-1 text-center text-xs text-ui-ink-gray-400">
							{{ name }}
						</p>

						<p
							class="mb-4 rounded-xl bg-ui-surface-gray-50 px-3 py-2.5 text-[11px] text-ui-ink-gray-600"
						>
							{{ doctype }} ditarik dari PIC
							<span class="font-semibold">{{ namaPic || '-' }}</span>
							dan kembali ke Stok.
						</p>

						<label class="mb-1 block font-medium text-ui-ink-gray-600">
							Alasan <span class="text-ui-ink-red-500">*</span>
						</label>
						<textarea
							v-model="alasan"
							rows="3"
							placeholder="Tulis alasan"
							class="w-full rounded-xl border border-ui-line-gray-300 px-3 py-2.5 text-xs text-ui-ink-gray-800 focus:border-primary focus:outline-none"
						></textarea>

						<p
							v-if="error"
							class="mt-2 rounded-xl bg-ui-surface-red-50 px-3 py-2.5 text-[11px] text-ui-ink-red-600"
						>
							{{ error }}
						</p>

						<div class="mt-4 flex gap-2">
							<button
								type="button"
								class="flex-1 rounded-full border border-ui-line-gray-200 py-3 text-sm font-medium text-ui-ink-gray-500 transition active:bg-ui-surface-gray-50"
								@click="tutup"
							>
								Kembali
							</button>
							<button
								type="button"
								:disabled="submitting"
								class="flex-1 rounded-full bg-primary py-3 text-sm font-semibold text-white transition active:scale-[0.99] disabled:cursor-not-allowed disabled:opacity-40"
								@click="submit"
							>
								{{ submitting ? 'Memproses…' : 'Kembalikan ke Stok' }}
							</button>
						</div>
					</div>
				</Transition>
			</div>
		</Transition>
	</Teleport>
</template>

<script setup>
import { ref, watch } from 'vue'
import { call } from 'frappe-ui'

const props = defineProps({
	open: { type: Boolean, default: false },
	doctype: { type: String, required: true },
	name: { type: String, default: '' },
	namaPic: { type: String, default: '' },
})
const emit = defineEmits(['update:open', 'done'])

const alasan = ref('')
const error = ref('')
const submitting = ref(false)

watch(
	() => props.open,
	(isOpen) => {
		if (!isOpen) return
		alasan.value = ''
		error.value = ''
	}
)

function tutup() {
	if (submitting.value) return
	emit('update:open', false)
}

async function submit() {
	if (submitting.value) return
	// Server juga menolak alasan kosong; dicek di sini supaya tidak perlu kirim dulu.
	if (!alasan.value.trim()) {
		error.value = 'Alasan wajib diisi.'
		return
	}
	submitting.value = true
	error.value = ''
	try {
		const r = await call('juragan.collection.kembalikan_stok.kembalikan_ke_stok', {
			doctype: props.doctype,
			name: props.name,
			alasan: alasan.value.trim(),
		})
		emit('update:open', false)
		emit('done', r)
	} catch (e) {
		error.value =
			e?.messages?.[0] || e?.message || String(e) || 'Gagal mengembalikan ke Stok.'
	} finally {
		submitting.value = false
	}
}
</script>
